  "stub": {
    "language": "asm",
    "source": "guard:\n    xor ecx, ecx\nloop:\n    mov al, byte [rsi+rcx]\n    test al, al\n    je terminate\n    cmp ecx, 31\n    jae invalid\n    mov byte [rdi+rcx], al\n    inc rcx\n    jmp loop\nterminate:\n    mov byte [rdi+rcx], 0\n    ret\ninvalid:\n    mov eax, 1\n    mov edi, 2\n    lea rsi, [rip+invalid_msg]\n    mov edx, 42\n    syscall\n    mov eax, 60\n    mov edi, 1\n    syscall",
