      "criterion": "max_valid_input_bytes",
      "how": "When rcx reaches 31 and the source byte is not NUL, the guard jumps to invalid. Therefore at most 31 data bytes are copied."
    },
    {
      "criterion": "valid_domain",
      "how": "For printable ASCII inputs of length 0..31 with no NUL, the guard copies and terminates normally and returns to the original puts. The guard does not alter printability; it enforces the length bound."
    },
    {
      "criterion": "valid_behavior",
      "how": "After normal return, the unmodified code at 0x40119d calls puts on the stack buffer, producing the input followed by a single LF, and the unmodified main returns 0."
    },
    {
      "criterion": "forbidden_behavior",
      "how": "All writes to the destination are indexed by rcx. Data writes occur only when rcx < 31; the terminate path writes at rcx <= 31. No write to dest[32] or beyond is possible."
    },
    {
      "criterion": "invalid_response",
      "how": "On length overflow, the stub performs write(2, invalid_stderr, 42) and then exit(1), writing nothing to stdout and not returning to the damaged frame."
